using System.ComponentModel;
using System.Net.Http.Json;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class ExternalApiTool
{
    [McpServerTool("fetch_data"), Description("Fetches data from an external API for the given resource path.")]
    public async Task<string> FetchDataAsync(
        IHttpClientFactory httpClientFactory,
        [Description("The resource path to query (e.g. \"users/1\")")] string path,
        CancellationToken cancellationToken = default)
    {
        using var client = httpClientFactory.CreateClient("ExternalApi");

        var response = await client.GetAsync(path, cancellationToken);
        response.EnsureSuccessStatusCode();

        var content = await response.Content.ReadAsStringAsync(cancellationToken);
        return content;
    }
}

using System.ComponentModel;
using ModelContextProtocol.Server;

namespace McpServer.Prompts;

[McpServerPromptType]
public sealed class SummarizationPrompt
{
    [McpServerPrompt("summarize"), Description("Summarizes the provided text into a concise overview.")]
    public static IList<Microsoft.Extensions.AI.ChatMessage> Summarize(
        [Description("The text content to summarize")] string content,
        [Description("Desired summary style: brief, detailed, or bullet-points")] string style = "brief")
    {
        return
        [
            new(Microsoft.Extensions.AI.ChatRole.User,
                $"""
                Summarize the following text in a {style} style.

                Text:
                {content}
                """)
        ];
    }
}

